Lemma unreg_iter_tail : forall (A K odr : Z) (w0 w1 w2 w3 w4 w5 w6 : word)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem) (o1 o2 o3 o4 : byte),
  ro_cells asegs m A [C8 w0; C8 w1; C8 w2; C8 w3; C8 w4; C8 w5; C8 w6; C8 (Z_to_bv 64 odr)] ->
  rw_cells asegs m 0x63f302 [C1 o1] -> rw_cells asegs m 0x63f300 [C1 o2] -> rw_cells asegs m 0x63f301 [C1 o3] -> rw_cells asegs m 0x63f303 [C1 o4] ->
  (odr = ODR_NONE \/ odr = 0x63f302 \/ odr = 0x63f300 \/ odr = 0x63f301 \/ odr = 0x63f303) ->
  0x102520 <= A -> A + 64 <= 0x1095a0 -> 1 <= K <= 450 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' : byte),
        ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x19e7a8) a0' a1' a2' a3' a4' a5' a6' a7'
                      (Z_to_bv 64 2) (Z_to_bv 64 0x1d600) (Z_to_bv 64 (A + 64)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x10a4f0)
                      (Z_to_bv 64 0xff9e0) (Z_to_bv 64 0x10a530) (Z_to_bv 64 0x10a478) (Z_to_bv 64 0x10cc78) (Z_to_bv 64 (K - 1))
                      t3' t4' t5' t6')
                 F (Z_to_bv 64 (if K =? 1 then 0x546dc else 0x544d8)) fc None m' (seg_rom asegs)
        /\ munch [(0x63f302, 0x63f304); (0x63f300, 0x63f302)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ rw_cells asegs m' 0x63f302 [C1 o1'] /\ rw_cells asegs m' 0x63f300 [C1 o2'] /\ rw_cells asegs m' 0x63f301 [C1 o3'] /\ rw_cells asegs m' 0x63f303 [C1 o4'])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x19e7a8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x1d600) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x10a4f0)
             (Z_to_bv 64 0xff9e0) (Z_to_bv 64 0x10a530) (Z_to_bv 64 0x10a478) (Z_to_bv 64 0x10cc78) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0x544c0) fc None m (seg_rom asegs)).
